[MATH: {X} =
\left\lbrack
\matrix {
{\color{red}7} & {\color{red}2} & {\color{red}-4} \
{\color{blue}-3} & {\color{blue}1} & {\color{blue}0}
}
\right\rbrack

\qquad\implies\qquad

{X}^T =
\left\lbrack
\matrix {
{\color{red}7} & {\color{blue}-3} \
{\color{red}2} & {\color{blue}1} \
{\color{red}-4} & {\color{blue}0}
}
\right\rbrack]

[MATH: {A} =
\left\lbrack
\matrix {
\color{red}{3} & \color{blue}{7} \
1 & \color{red}{6}
}
\right\rbrack

\qquad \implies\qquad

{A}^T =
\left\lbrack
\matrix {
\color{red}{3} & 1 \
\color{blue}{7} & \color{red}{6}
}
\right\rbrack.]

[MATH: {A} =
\left\lbrack
\matrix {
\color{red}{3} & \color{blue}{7} \
1 & \color{red}{6}
}
\right\rbrack

\quad \implies\quad

{A}^T =
\left\lbrack
\matrix {
\color{red}{3} & 1 \
\color{blue}{7} & \color{red}{6}
}
\right\rbrack

\quad \implies\quad

\left( {A}^T\right)^T =
\left\lbrack
\matrix {
\color{red}{3} & \color{blue}{7} \
1 & \color{red}{6}
}
\right\rbrack =A.]
